<script setup lang="ts">
import { onMounted,reactive,ref } from 'vue'
import type { CatalogoDetraccion,CatalogoDetraccionPayload } from '../interfaces/catalogo-detraccion.interface'
import { cambiarEstadoCatalogoDetraccion,guardarCatalogoDetraccion,listarCatalogoDetracciones,obtenerCatalogoDetraccion } from '../services/catalogo-detraccion'
const blank=():CatalogoDetraccionPayload=>({codigo:'',descripcion:'',porcentaje:0,monto_minimo:null,codigo_operacion:'',observacion:'',vigente_desde:'',vigente_hasta:''})
const rows=ref<CatalogoDetraccion[]>([]),buscar=ref(''),estado=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),showForm=ref(false),editing=ref<number|null>(null),form=reactive(blank())
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',date=(v?:string|null)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'Sin límite',money=(v?:number|null)=>v==null?'-':new Intl.NumberFormat('es-PE',{style:'currency',currency:'PEN'}).format(v)
async function load(next=1){loading.value=true;error.value='';try{const r=await listarCatalogoDetracciones(buscar.value,estado.value,next);rows.value=r.data;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
function create(){editing.value=null;Object.assign(form,blank());showForm.value=true}
async function edit(item:CatalogoDetraccion){loading.value=true;try{const x=await obtenerCatalogoDetraccion(item.id);editing.value=x.id;Object.assign(form,blank(),x,{monto_minimo:x.monto_minimo??null,vigente_desde:x.vigente_desde?.slice(0,10)||'',vigente_hasta:x.vigente_hasta?.slice(0,10)||''});showForm.value=true}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){if(form.vigente_desde&&form.vigente_hasta&&form.vigente_desde>form.vigente_hasta){error.value='La fecha final no puede ser menor que la fecha inicial.';return}loading.value=true;error.value='';try{await guardarCatalogoDetraccion(editing.value,{...form});success.value=`Catálogo ${editing.value?'actualizado':'registrado'} correctamente.`;showForm.value=false;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(item:CatalogoDetraccion){const action=item.activo?'inactivar':'activar';if(!confirm(`¿Desea ${action} el código ${item.codigo}?`))return;loading.value=true;try{await cambiarEstadoCatalogoDetraccion(item.id);success.value=`Catálogo ${item.activo?'inactivado':'activado'} correctamente.`;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){buscar.value='';estado.value='';load(1)}
onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Catálogo de detracciones</nav><header class="hero"><div class="mark">%</div><div><small>MIA · FINANZAS · MAESTROS</small><h1>Catálogo de detracciones</h1><p>Códigos, porcentajes, montos mínimos y periodos de vigencia.</p></div><strong>{{total}} registros</strong><button @click="create">+ Nueva detracción</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="buscar" placeholder="Buscar código, descripción o código de operación"><select v-model="estado"><option value="">Todos los estados</option><option value="1">Activos</option><option value="0">Inactivos</option></select><button>Buscar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron detracciones.</div><div v-else class="scroll"><table><thead><tr><th>Código</th><th>Descripción</th><th>Operación</th><th>Porcentaje</th><th>Monto mínimo</th><th>Vigencia</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.codigo}}</b></td><td>{{item.descripcion}}<small v-if="item.observacion">{{item.observacion}}</small></td><td>{{item.codigo_operacion||'-'}}</td><td><b>{{Number(item.porcentaje).toFixed(4)}}%</b></td><td>{{money(item.monto_minimo)}}</td><td>{{date(item.vigente_desde)}}<small>hasta {{date(item.vigente_hasta)}}</small></td><td><span :class="item.activo?'good':'bad'">{{item.activo?'ACTIVO':'INACTIVO'}}</span></td><td class="actions"><button class="edit" @click="edit(item)">Editar</button><button :class="item.activo?'danger':'activate'" @click="toggle(item)">{{item.activo?'Inactivar':'Activar'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section><div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO REGISTRO'}}</small><h2>{{editing?'Editar':'Registrar'}} detracción</h2></div><button type="button" @click="showForm=false">×</button></header><div class="grid"><label>Código<input v-model.trim="form.codigo" maxlength="10" required></label><label>Código de operación<input v-model.trim="form.codigo_operacion" maxlength="10"></label><label class="span2">Descripción<input v-model.trim="form.descripcion" maxlength="250" required></label><label>Porcentaje<input v-model.number="form.porcentaje" type="number" min="0.0001" max="100" step="0.0001" required></label><label>Monto mínimo<input v-model.number="form.monto_minimo" type="number" min="0" step="0.0001"></label><label>Vigente desde<input v-model="form.vigente_desde" type="date"></label><label>Vigente hasta<input v-model="form.vigente_hasta" type="date"></label><label class="span2">Observación<textarea v-model.trim="form.observacion" maxlength="1000" rows="4"></textarea></label></div><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading">Guardar</button></footer></form></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-size:1.25rem;font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small{color:var(--a);font-size:.5rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:2fr 1fr auto auto;gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog textarea{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.52rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1050px;border-collapse:collapse;font-size:.5rem}th,td{padding:10px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.good,.bad{display:inline-block;padding:4px 8px;border-radius:10px;font-size:.47rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.actions{display:flex;gap:5px}.edit{background:#c98a24}.danger{background:#b74b54}.activate{background:#27875f}.empty{padding:45px;text-align:center}.card>footer,.dialog>footer{padding:12px;display:flex;justify-content:center;align-items:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);max-height:92vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}.grid label{display:grid;gap:5px;color:#5d7078;font-size:.52rem;font-weight:700}.grid textarea{resize:vertical}.span2{grid-column:span 2}@media(max-width:650px){.filters,.grid{grid-template-columns:1fr}.span2{grid-column:auto}.hero{align-items:flex-start;flex-wrap:wrap}.hero .mark{display:none}}
</style>
